def slug(text):
    """
    Convert text to a slug: lowercase ASCII letters and digits, 
    replace each run of other characters with one hyphen, and trim hyphens.

    Only handles ASCII characters (0-127).
    """
    # Convert to lowercase and process each character
    result = []
    for char in text.lower():
        if char.isalnum():
            result.append(char)
        else:
            # Only replace non-alphanumeric ASCII characters with a hyphen
